import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useOnce } from '../../query/useOnce';
import { postJson } from '../../api/http';
import { useSheetId } from './session';

type Sheet = { id: string };

// Choose a sheet by typing its id and loading it. An id never used before starts an empty sheet;
// loading an id again drops what was cached for it, so the sheet is re-read from the store.
export function SheetLoader({ onLoaded }: { onLoaded: () => void }) {
  const queryClient = useQueryClient();
  const [sheetId, setSheetId] = useSheetId();
  const [input, setInput] = useState('');
  const [error, setError] = useState('');

  const once = useOnce();
  const load = useMutation({
    mutationFn: (id: string) => postJson<Sheet>(`/api/sheets/${encodeURIComponent(id)}/load`, {}),
    onSuccess: (sheet) => {
      queryClient.removeQueries({ queryKey: ['sheet', sheet.id] });
      setSheetId(sheet.id);
      onLoaded();
    },
    onError: () => setError('That sheet could not be loaded.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const id = input.trim();
    if (id === '') {
      setError('Type a sheet id to load.');
      return;
    }
    once((done) => load.mutate(id, { onSettled: done }));
  };

  return (
    <form onSubmit={submit} data-testid="sheet-form">
      <label>
        Sheet{' '}
        <input
          data-testid="sheet-id-input"
          value={input}
          onChange={(e) => {
            setInput(e.target.value);
            setError('');
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="sheet-load" disabled={load.isPending}>
        Load
      </button>{' '}
      {sheetId && (
        <span>
          Active sheet: <strong data-testid="sheet-current-id">{sheetId}</strong>
        </span>
      )}
      {error && (
        <p role="alert" data-testid="sheet-load-error">
          {error}
        </p>
      )}
    </form>
  );
}
}

function DueHead() {
  return <th>Due</th>;
}

// A person's due-total: the due figures of their claims that count, added up.
function PersonDueTotal({ sheetId, person }: { sheetId: string; person: Person }) {
  const claims = (useClaims(sheetId).data ?? []).filter((c) => c.personId === person.id);
  const rates = useRates(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  return <td data-testid="person-due-total">{personDueTotal(rates, person.grade, today, claims, person.held)}</td>;
}

// The sheet's due-total: everyone's due-total added up, skipping those with no rate.
function DueTotal({ sheetId }: { sheetId: string }) {
  const people = usePeople(sheetId).data ?? [];
  const claims = useClaims(sheetId).data ?? [];
  const rates = useRates(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  const totals = people.map((p) =>
    personDueTotal(rates, p.grade, today, claims.filter((c) => c.personId === p.id), p.held),
  );
  return (
    <p>
      Due in all: <strong data-testid="rollup-due-total">{sumDue(totals)}</strong>
    </p>
  );
}

export const contributions = [
  SheetBody.fill({ order: -10, Component: Rates }),
  SheetBody.fill({ order: 20, Component: DueTotal }),
  PersonHead.fill({ order: 20, Component: DueHead }),
  PersonRow.fill({ order: 20, Component: PersonDueTotal }),
];
